mod common;
use docconvert::{config::{Options,OcrMode},convert,error::ConvertError,extract::image::read_dimensions,model::ImageKind,ocr};
#[test]fn all_header_dimensions_and_truncation(){let png=common::png();let gif=b"GIF89a\x02\0\x03\0".to_vec();let jpeg=b"\xff\xd8\xff\xc0\0\x11\x08\0\x03\0\x02\x03\x01\x11\0\x02\x11\0\x03\x11\0".to_vec();let mut bmp=vec![0;26];bmp[..2].copy_from_slice(b"BM");bmp[14..18].copy_from_slice(&12u32.to_le_bytes());bmp[18..20].copy_from_slice(&2u16.to_le_bytes());bmp[20..22].copy_from_slice(&3u16.to_le_bytes());let mut webp=b"RIFF\x16\0\0\0WEBPVP8X\x0a\0\0\0\0\0\0\0\x01\0\0\x02\0\0".to_vec();webp[4..8].copy_from_slice(&22u32.to_le_bytes());let tiff=b"II*\0\x08\0\0\0\x02\0\0\x01\x03\0\x01\0\0\0\x02\0\0\0\x01\x01\x03\0\x01\0\0\0\x03\0\0\0".to_vec();let jp2=b"\0\0\0\x16ihdr\0\0\0\x03\0\0\0\x02\0\x03\x07\x07\0\0".to_vec();for(kind,bytes,expected)in [(ImageKind::Png,png,(1,1)),(ImageKind::Gif,gif,(2,3)),(ImageKind::Jpeg,jpeg,(2,3)),(ImageKind::Bmp,bmp,(2,3)),(ImageKind::Webp,webp,(2,3)),(ImageKind::Tiff,tiff,(2,3)),(ImageKind::Jp2,jp2,(2,3))]{assert_eq!(read_dimensions(&bytes,kind),Some(expected),"{kind:?}");assert_eq!(read_dimensions(&[],kind),None,"{kind:?} empty");assert_eq!(read_dimensions(&bytes[..1.min(bytes.len())],kind),None,"{kind:?} 1-byte");for n in 0..bytes.len(){let _=read_dimensions(&bytes[..n],kind);}}}
#[test]fn missing_engine_auto_preserves_image_force_errors(){let t=common::Temp::new();let input=t.write("photo.png",&common::png());let opts=Options{output:Some(t.0.join("out")),ocr_mode:OcrMode::Auto,ocr_command:t.0.join("no-engine").to_string_lossy().into_owned(),..Options::default()};let report=convert::convert_file(&input,&opts).unwrap();assert_eq!(report.ocr_status,"engine unavailable");assert_eq!(report.image_dimensions[0].1,Some((1,1)));let force=Options{ocr_mode:OcrMode::Force,output:Some(t.0.join("forced")),..opts};assert!(matches!(convert::convert_file(&input,&force),Err(ConvertError::Ocr(s))if s=="OCR engine not found"));assert!(!t.0.join("forced").exists());}
#[test]fn fake_engine_argv_and_cleanup(){let t=common::Temp::new();let engine=common::fake_ocr(&t.0);let opts=Options{ocr_mode:OcrMode::Force,ocr_command:engine.to_string_lossy().into_owned(),ocr_lang:"eng; echo NOT_A_SHELL".into(),..Options::default()};let result=ocr::run_ocr(&common::png(),&opts).unwrap();assert!(result.text.contains("OCR fixture text"));assert!(result.text.contains("eng; echo NOT_A_SHELL"));assert_eq!(result.confidence,None);let scratch=result.text.lines().find_map(|l|l.strip_prefix("Scratch: ")).unwrap();assert!(!std::path::Path::new(scratch).exists());let fail=Options{ocr_lang:"fail".into(),..opts};assert!(matches!(ocr::run_ocr(&common::png(),&fail),Err(ConvertError::Ocr(s))if s=="engine exited unsuccessfully: fixture failure"));}
#[test]fn standalone_ocr_end_to_end(){let t=common::Temp::new();let engine=common::fake_ocr(&t.0);let input=t.write("scan.png",&common::png());let opts=Options{ocr_mode:OcrMode::Auto,ocr_command:engine.to_string_lossy().into_owned(),output:Some(t.0.join("out")),..Options::default()};let report=convert::convert_file(&input,&opts).unwrap();let output=std::fs::read_to_string(t.0.join("out").join(format!("scan.{}",report.output_format))).unwrap();assert!(output.contains("OCR fixture text"));}
